list_customer_groups.code:
use WebCommander\Sdk\Resources\CustomerGroups\CustomerGroups;

$response = CustomerGroups::listCustomerGroups($client, ['search_text' => 'wholesale', 'status' => 'active', 'limit' => 50]);

foreach ($response->map['customer_groups'] as $group) {
    echo $group['id'], ' ', $group['name'], ' ', $group['status'], PHP_EOL;
}
echo $response->map['pagination']['has_next'] ? 'more pages' : 'last page', PHP_EOL;

create_customer_group.code:
use WebCommander\Sdk\Resources\CustomerGroups\CustomerGroups;

$response = CustomerGroups::createCustomerGroup($client, ['customer_group' => [
    'name' => 'Wholesale Partners', 'description' => 'Trade accounts', 'status' => 'active',
    'purchase_preference' => [
        'minimum_purchase' => ['enabled' => true, 'amount' => 50],
        'on_account_purchase' => [
            'enabled' => true, 'max_purchase' => ['enabled' => true, 'amount' => 500],
            'credit_limit' => ['enabled' => true, 'amount' => 1000], 'payment_terms' => ['enabled' => true, 'terms' => 'NET_30'],
        ],
    ],
    'tax_configuration' => [
        'override_store_tax' => true, 'tax_exempt' => false, 'tax_message' => 'Prices exclude GST',
        'show_prices_with_tax_included' => true, 'prices_entered_with_tax_included' => false, 'base_price_rounding' => 'up',
    ],
    'product_display' => [
        'overwrite_default' => true, 'variation_display_type' => 'enable_matrix_view', 'display_parent_image' => true,
        'activate_colour_variation_image' => false, 'show_selected_variation_value' => true,
        'strike_through_out_of_stock' => false, 'single_click_variation_loading' => true, 'price_display_method' => 'highest',
    ],
]]);

$group = $response->map['customer_group'];
echo $group['id'], ' ', $group['status'], ' ', $group['purchase_preference']['on_account_purchase']['payment_terms']['terms'], PHP_EOL;

get_customer_group.code:
use WebCommander\Sdk\Resources\CustomerGroups\CustomerGroups;

$response = CustomerGroups::getCustomerGroup($client, 1234);

$group = $response->map['customer_group'];
echo $group['name'], ' ', $group['status'], ' ', $group['customer_count'], PHP_EOL;
foreach ($group['customers'] as $customer) {
    echo $customer['id'], ' ', $customer['email'], PHP_EOL;
}

update_customer_group_customers.code:
use WebCommander\Sdk\Resources\CustomerGroups\CustomerGroups;

$response = CustomerGroups::updateCustomerGroupCustomers($client, 1234, ['customers' => [5678, '5679']]);

$group = $response->map['customer_group'];
echo $group['customer_count'], PHP_EOL;
foreach ($group['customers'] as $customer) {
    echo $customer['id'], ' ', $customer['email'], PHP_EOL;
}
